// Release builds of this app have NO internet permission: Android itself then blocks every network
// call, so the app is provably offline. Debug builds keep it (the dev server needs it), which is why
// this lives in the release-only manifest instead of app.json's blockedPermissions.
const { withDangerousMod } = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MANIFEST = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/withOfflineRelease.js: release builds never get network access. -->
<manifest xmlns:android="http://schemas.android.com/apk/res/android" xmlns:tools="http://schemas.android.com/tools">
  <uses-permission android:name="android.permission.INTERNET" tools:node="remove" />
  <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" tools:node="remove" />
</manifest>
`;

module.exports = function withOfflineRelease(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'release');
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, 'AndroidManifest.xml'), MANIFEST);
      return cfg;
    },
  ]);
};

module.exports.MANIFEST = MANIFEST;
